using System.Collections.Generic;

var stack = new Stack<int>();

// Push — O(1)
stack.Push(10);
stack.Push(20);
stack.Push(30);

// Peek — O(1)
Console.WriteLine(stack.Peek());  // 30

// Pop — O(1)
Console.WriteLine(stack.Pop());   // 30

// Count
Console.WriteLine(stack.Count);   // 2

class Stack:
  def __init__(self):
      self.items = []

  def push(self, item):
      self.items.append(item)

  def pop(self):
      if self.is_empty():
          raise IndexError("Stack is empty")
      return self.items.pop()

  def peek(self):
      if self.is_empty():
          raise IndexError("Stack is empty")
      return self.items[-1]

  def is_empty(self):
      return len(self.items) == 0

  def size(self):
      return len(self.items)

# Usage
stack = Stack()
stack.push(10)
stack.push(20)
stack.push(30)
print(stack.peek())  # 30
print(stack.pop())   # 30
print(stack.size())  # 2

package main

import "fmt"

func main() {
  var stack []int

  // Push — O(1)
  stack = append(stack, 10, 20, 30)

  // Peek — O(1)
  fmt.Println(stack[len(stack)-1])  // 30

  // Pop — O(1)
  top := stack[len(stack)-1]
  stack = stack[:len(stack)-1]
  fmt.Println(top)  // 30

  fmt.Println(len(stack))  // 2
}
